import request from "supertest";
import jwt from "jsonwebtoken";
import app from "../../src/app.js";
import {
  closeDatabase,
  createUser,
  syncDatabase,
  truncateDatabase,
} from "../setup/testDatabase.js";
import { JWT_SECRET } from "../../src/config/auth.js";
import { Room } from "../../src/models/index.js";

function authHeader(user) {
  return `Bearer ${jwt.sign({ id: user.id, role: user.role }, JWT_SECRET)}`;
}

describe("Room routes", () => {
  beforeAll(async () => {
    await syncDatabase();
  });

  beforeEach(async () => {
    await truncateDatabase();
  });

  afterAll(async () => {
    await closeDatabase();
  });

  test("creates a new room for authenticated user", async () => {
    const user = await createUser();

    const response = await request(app)
      .post("/api/room/create")
      .set("Authorization", authHeader(user))
      .send({
        password: "12345678",
      });

    expect(response.status).toBe(201);
    expect(response.body.code).toEqual(expect.any(Number));
  });

  test("enters an existing room by code for authenticated user", async () => {
    const user = await createUser();
    const room = await Room.create({
      password: "12345678",
      code: 123456,
      userId: user.id,
    });

    const response = await request(app)
      .get(`/api/room/${room.code}`)
      .set("Authorization", authHeader(user))
      .send({
        code: room.code,
      });

    expect(response.status).toBe(200);
    expect(response.body.message).toBe("Room was found successfully");
  });

  test("deletes a room for authenticated user", async () => {
    const user = await createUser();
    const room = await Room.create({
      password: "12345678",
      code: 123456,
      userId: user.id,
    });

    const response = await request(app)
      .delete(`/api/room/delete`)
      .set("Authorization", authHeader(user))
      .send({
        pass: "12345678",
        code: room.code,
      });

    expect(response.status).toBe(200);
    expect(response.body.message).toBe("sala excluída com sucesso");
  });

  test("lists rooms for authenticated admin user", async () => {
    const adminUser = await createUser({ role: "admin" });
    const user = await createUser();

    await Room.create({
      password: "12345678",
      code: 123456,
      userId: user.id,
    });

    const response = await request(app)
      .get("/api/room/admin/list")
      .set("Authorization", authHeader(adminUser));

    expect(response.status).toBe(200);
    expect(response.body.rooms).toHaveLength(1);
    expect(response.body.rooms[0]).toHaveProperty("code", 123456);
  });

  test("returns 403 for non-admin user trying to list rooms", async () => {
    const user = await createUser();

    await Room.create({
      password: "12345678",
      code: 123456,
      userId: user.id,
    });

    const response = await request(app)
      .get("/api/room/admin/list")
      .set("Authorization", authHeader(user));

    expect(response.status).toBe(403);
    expect(response.body).toHaveProperty("error", "Não autorizado!");
  });
});
